def test_reexports_exist():
    assert ContextDecorator is not None
    assert contextmanager is not None
    assert unwrap is not None


def test_unwrap_reexport_works():
    def f():
        pass

    @functools.wraps(f)
    def wrapper():
        pass

    assert unwrap(wrapper) is f
